export function openSheetWorkspace(){if(dialog.open)return;opener=document.activeElement;try{const stored=JSON.parse(localStorage.getItem(KEY));book=stored?.version===1&&Array.isArray(stored.sheets)&&stored.sheets.length?stored:newBook();}catch{book=newBook();}for(const s of book.sheets)if(s.highlight){s.conditional||=[];s.conditional.push({id:crypto.randomUUID(),type:'gt',range:s.highlight.range,a:String(s.highlight.threshold),b:'',fill:'#fff0c2',color:'#203d31',enabled:true});delete s.highlight;}tab='home';start=end='A1';undo=[];redo=[];clipboardCells=null;formatBrush=null;filter='';panel='welcome';saved=true;render();dialog.showModal();}
