function render(){dialog.innerHTML='<header class="sx-title"><span class="sx-app-icon">'+icon('grid')+'</span><div><small>ARLES · HOJAS DE CÁLCULO</small><input data-book-name aria-label="Nombre del libro" value="'+esc(book.name)+'" maxlength="100"></div><span class="sx-save-state"></span><div class="sx-title-actions">'+button('undo','Deshacer','undo')+button('redo','Rehacer','undo')+button('save','Guardar','save')+'<button data-sx="close" aria-label="Cerrar hojas de cálculo">×</button></div></header><nav class="sx-tabs" aria-label="Cinta de hoja de cálculo">'+tabs.map(([id,n])=>'<button data-sx-tab="'+id+'" aria-selected="'+(tab===id)+'">'+n+'</button>').join('')+'<span>Diseño inicial · 100 filas × 26 columnas</span></nav><div class="sx-ribbon">'+ribbon()+'</div><div class="sx-formula"><input data-address aria-label="Celda o rango" value="'+start+'"><span>ƒx</span><input data-formula aria-label="Barra de fórmulas" placeholder="Escribe un valor o una fórmula, por ejemplo =SUMA(B2:B8)"><button data-sx="commit-formula" aria-label="Aplicar fórmula">✓</button></div><main class="sx-main"><div class="sx-grid-scroll" tabindex="0" aria-label="Área de celdas"><table class="sx-grid" role="grid" aria-label="Hoja de cálculo"></table></div><aside class="sx-panel"></aside></main><footer class="sx-bottom"><div class="sx-sheets"></div><div class="sx-status"><span data-sx-message role="status">Listo · Selecciona un rango arrastrando o con Mayús.</span><span data-sx-stats></span><label>Zoom <input data-zoom type="range" min="70" max="150" step="10" value="'+zoom+'"><output>'+zoom+' %</output></label></div></footer>';renderGrid();renderSheets();renderPanel();sync();}
function renderSheets(){dialog.querySelector('.sx-sheets').innerHTML=book.sheets.map((s,i)=>'<button data-sheet="'+i+'" aria-pressed="'+(i===book.active)+'">'+icon('grid')+esc(s.name)+(s.protected?' 🔒':'')+'</button>').join('')+'<button data-sx="add-sheet" aria-label="Añadir hoja">＋</button><button data-sx="rename" title="Cambiar nombre de hoja">Renombrar</button>';}
function mergedAnchor(ref){return (sheet().merges||[]).find(m=>range(m).includes(ref))?.split(':')[0]||ref;}
function renderGrid(){
 const s=sheet(),table=dialog.querySelector('.sx-grid'),conditions=conditionalStyles(s),merges=new Map(),covered=new Set();
 for(const m of s.merges||[]){const refs=range(m),a=position(refs[0]),b=position(refs.at(-1));merges.set(refs[0],[b[0]-a[0]+1,b[1]-a[1]+1]);refs.slice(1).forEach(x=>covered.add(x));}
 table.style.zoom=zoom/100;table.classList.toggle('sx-no-grid',!s.grid);table.classList.toggle('sx-freeze',!!s.freeze);
 let html='<colgroup><col style="width:43px">'+Array.from({length:COLS},(_,c)=>'<col style="width:'+(s.columnWidths?.[c]||112)+'px">').join('')+'</colgroup><thead><tr><th aria-label="Seleccionar todo" data-all>◩</th>'+Array.from({length:COLS},(_,c)=>'<th scope="col" data-col="'+c+'" style="width:'+(s.columnWidths?.[c]||112)+'px;min-width:'+(s.columnWidths?.[c]||112)+'px">'+address(0,c).slice(0,-1)+'</th>').join('')+'</tr></thead><tbody>';
 for(let r=0;r<ROWS;r++){const hidden=filter&&r>0&&!Array.from({length:COLS},(_,c)=>display(s,address(r,c))).join(' ').toLowerCase().includes(filter.toLowerCase());html+='<tr '+(hidden?'hidden':'')+' style="height:'+(s.rowHeights?.[r]||27)+'px"><th scope="row" data-row="'+r+'">'+(r+1)+'</th>';
  for(let c=0;c<COLS;c++){const ref=address(r,c);if(covered.has(ref))continue;const cell=s.cells[ref]||{},v=display(s,ref),effect=conditions.get(ref)||{},merge=merges.get(ref),width=Array.from({length:merge?.[1]||1},(_,i)=>s.columnWidths?.[c+i]||112).reduce((a,b)=>a+b,0);
   const border=cell.border===true||cell.border==='all'?'inset 0 0 0 1px #718a7a':cell.border==='bottom'?'inset 0 -1px #718a7a':cell.border==='top'?'inset 0 1px #718a7a':cell.border==='double'?'inset 0 -1px #718a7a,inset 0 -3px white,inset 0 -4px #718a7a':'none';const style='width:'+width+'px;min-width:'+width+'px;max-width:'+width+'px;font-family:'+esc(cell.font||'Arial')+';font-size:'+(cell.size||11)+'pt;font-weight:'+(cell.bold?'700':'400')+';font-style:'+(cell.italic?'italic':'normal')+';color:'+esc(effect.color||cell.color||'#203d31')+';background-color:'+esc(effect.fill||cell.fill||'#ffffff')+';text-align:'+(cell.align||(typeof value(s,ref)==='number'?'right':'left'))+';text-decoration:'+(cell.underline?'underline':'none')+';vertical-align:'+(cell.valign||'bottom')+';box-shadow:'+border+';white-space:'+(cell.wrap?'normal':'nowrap')+';padding-left:'+(6+(cell.indent||0)*10)+'px';
   html+='<td role="gridcell" data-sx-cell="'+ref+'" aria-label="'+ref+'" '+(merge?'rowspan="'+merge[0]+'" colspan="'+merge[1]+'" ':'')+(cell.note?'title="Nota: '+esc(cell.note)+'"':'')+' style="'+style+'" class="'+(cell.note?'sx-has-note':'')+(v.startsWith('#')?' sx-error':'')+'">'+(effect.bar?'<i class="sx-data-bar" style="left:'+effect.bar.left+'%;width:'+effect.bar.width+'%;background:'+(effect.bar.negative?'#d98479':'#77b3d5')+'"></i>':'')+'<span class="sx-cell-text">'+(effect.icon?'<span aria-label="Indicador">'+effect.icon+'</span> ':'')+esc(v)+'</span></td>';
  }html+='</tr>';
 }table.innerHTML=html+'</tbody>';paintSelection();
}
function paintSelection(){const refs=new Set(selection());dialog.querySelectorAll('[data-sx-cell]').forEach(n=>{const selected=refs.has(n.dataset.sxCell);n.classList.toggle('sx-selected',selected);n.classList.toggle('sx-active',n.dataset.sxCell===mergedAnchor(start));n.setAttribute('aria-selected',String(selected));});sync();}
function sync(){if(!dialog.querySelector('[data-formula]'))return;const cell=current();for(const input of dialog.querySelectorAll('[data-setting]')){const defaults={font:'Arial',size:11,color:'#203d31',fill:'#ffffff',format:'general'};input.value=cell[input.dataset.setting]??defaults[input.dataset.setting];}for(const key of ['bold','italic','underline','wrap'])dialog.querySelector('[data-sx='+key+']')?.setAttribute('aria-pressed',String(!!cell[key]));dialog.querySelector('[data-formula]').value=current().raw||'';dialog.querySelector('[data-address]').value=start===end?start:start+':'+end;dialog.querySelector('.sx-save-state').textContent=saved?'En este navegador':'Cambios sin guardar';dialog.querySelector('[data-sx=undo]').disabled=!undo.length;dialog.querySelector('[data-sx=redo]').disabled=!redo.length;const nums=selection().map(ref=>value(sheet(),ref)).filter(v=>typeof v==='number');dialog.querySelector('[data-sx-stats]').textContent=selection().length>1?'Selección: '+selection().length+' · Suma: '+nums.reduce((a,b)=>a+b,0).toLocaleString('es-CO')+' · Promedio: '+(nums.length?nums.reduce((a,b)=>a+b,0)/nums.length:0).toLocaleString('es-CO',{maximumFractionDigits:2}):start;}
function format(key,val){change(()=>{if(sheet().protected)throw Error('Desprotege la hoja para cambiar su formato.');for(const ref of selection())sheet().cells[ref]={...sheet().cells[ref],[key]:val};});dialog.querySelector('.sx-ribbon').innerHTML=ribbon();}
function openPanel(name){panel=name;if(name==='conditional')editingRule=null;renderPanel();}
function conditionPanel(){const rule=sheet().conditional?.find(x=>x.id===editingRule)||{range:start+':'+end,type:'gt',a:'100',b:'200',fill:'#ffdfdd',color:'#9b3029',stop:false};return '<p>Las reglas se recalculan al editar. La primera regla tiene prioridad cuando dos cambian el mismo formato.</p><label>Aplicar a<input data-cf="range" value="'+esc(rule.range)+'"></label><label>Condición<select data-cf="type">'+Object.entries(CONDITION_TYPES).map(([v,n])=>'<option value="'+v+'" '+(rule.type===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label data-cf-value>Valor, texto o fórmula<input data-cf="a" value="'+esc(rule.a||'')+'"></label><label data-cf-second>Segundo límite<input data-cf="b" value="'+esc(rule.b||'')+'"></label><div class="sx-cf-colors"><label>Relleno<input type="color" data-cf="fill" value="'+rule.fill+'"></label><label>Texto<input type="color" data-cf="color" value="'+rule.color+'"></label></div><label><input type="checkbox" data-cf="stop" '+(rule.stop?'checked':'')+'> Detener si se cumple</label><small>Fórmula: =A1&gt;100 o =$B1="Pendiente". Las referencias relativas parten de la primera celda del rango.</small><div class="sx-cf-preview" data-cf-preview></div>'+button('apply-conditional',editingRule?'Guardar cambios de regla':'Añadir regla','conditional')+'<h3>Administrar reglas · '+(sheet().conditional?.length||0)+'</h3><div class="sx-cf-rules">'+(sheet().conditional||[]).map((r,i)=>'<article><label><input type="checkbox" data-cf-toggle="'+r.id+'" '+(r.enabled===false?'':'checked')+'> '+esc(CONDITION_TYPES[r.type])+'</label><small>'+esc(r.range)+' · '+esc(r.a||'')+'</small><div><button data-cf-edit="'+r.id+'">Editar</button><button data-cf-up="'+r.id+'" '+(i===0?'disabled':'')+' aria-label="Subir prioridad">↑</button><button data-cf-delete="'+r.id+'" aria-label="Eliminar regla">×</button></div></article>').join('')+'</div>'+button('new-conditional','Nueva regla','plus')+button('clear-conditional','Borrar reglas de la selección','eraser');}
